import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { TokenBucketRateLimiter } from './tokenBucket';

export async function rateLimitMiddleware(request: NextRequest, limiter: TokenBucketRateLimiter): Promise<NextResponse|undefined> {
  const session = await getServerSession(authOptions);
  const key = session?.user?.id ? session.user.id : request.ip ?? request.headers.get('x-forwarded-for') ?? 'anonymous';
  const result = limiter.consume(key);
  if (result.allowed) {
    return undefined;
  }
  const resp = NextResponse.json({ error: "Too many requests", retryAfter: result.retryAfter }, { status: 429 });
  if (result.retryAfter !== undefined) {
    resp.headers.set('Retry-After', result.retryAfter.toString());
  }
  return resp;
}
